66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /** Dedicated audit logger; each successful owner create emits one line here. */
72	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
73	
74	    /**
75	     * The header carrying an idempotency key for owner creation. When a create repeats with a key
76	     * already seen, the originally created owner is returned with 200 instead of creating a duplicate.
77	     */
78	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
79	
80	    /**
81	     * Remembers, per seen idempotency key, the id of the owner that create originally produced, so a
82	     * repeat of the same request returns that owner rather than creating a duplicate.
83	     */
84	    private final Map<String, Integer> idempotentCreates = new java.util.concurrent.ConcurrentHashMap<>();
85	
86	    private final ClinicService clinicService;
87	
88	    private final OwnerMapper ownerMapper;
89	
90	    private final PetMapper petMapper;
91	
92	    private final VisitMapper visitMapper;
93	
94	    public OwnerRestControllerV1(ClinicService clinicService,
95	                                 OwnerMapper ownerMapper,
96	                                 PetMapper petMapper,
97	                                 VisitMapper visitMapper) {
98	        this.clinicService = clinicService;
99	        this.ownerMapper = ownerMapper;
100	        this.petMapper = petMapper;
101	        this.visitMapper = visitMapper;
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
107	        Collection<Owner> owners;
108	        if (lastName != null) {
109	            owners = this.clinicService.findOwnerByLastName(lastName);
110	        } else {
111	            owners = this.clinicService.findAllOwners();
112	        }
113	        if (owners.isEmpty()) {
114	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
115	        }
116	        Map<String, Integer> householdSizes = householdSizes();
117	        List<OwnerDto> ownerDtos = new java.util.ArrayList<>();
118	        for (Owner owner : owners) {
119	            OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
120	            applyMembership(ownerDto, owner, householdSizes);
121	            ownerDtos.add(ownerDto);
122	        }
123	        return new ResponseEntity<>(ownerDtos, HttpStatus.OK);
124	    }
125	
126	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
127	    @Override
128	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
129	        Owner owner = this.clinicService.findOwnerById(ownerId);
130	        if (owner == null) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
134	        applyMembership(ownerDto, owner);
135	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
136	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
137	    }
138	
139	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
140	    @Override
141	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
142	        HttpHeaders headers = new HttpHeaders();
143	        String idempotencyKey = currentIdempotencyKey();
144	        if (idempotencyKey != null) {
145	            Integer existingId = idempotentCreates.get(idempotencyKey);
146	            if (existingId != null) {
147	                Owner existing = this.clinicService.findOwnerById(existingId);
148	                if (existing != null) {
149	                    OwnerDto existingDto = ownerMapper.toOwnerDto(existing);
150	                    applyMembership(existingDto, existing);
151	                    existingDto.setBulkSignupWarning(isBulkSignupDay());
152	                    return new ResponseEntity<>(existingDto, HttpStatus.OK);
153	                }
154	            }
155	        }
156	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
157	        String address = applyAddress(owner, ownerFieldsDto);
158	        if (address.isEmpty()) {
159	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
160	        }
161	        owner.setAddress(address);
162	        String telephone = toE164(owner.getTelephone());
163	        if (telephone == null) {
164	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
165	        }
166	        owner.setTelephone(telephone);
167	        if (owner.getEmail() != null) {
168	            String email = normalizeEmail(owner.getEmail());
169	            if (email == null) {
170	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
171	            }
172	            owner.setEmail(email);
173	        }
174	        if (owner.getPostcode() != null && !isValidPostcode(owner.getPostcode(), owner.getCity())) {
175	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
176	        }
177	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
178	        if (effectiveRegistrationDate == null) {
179	            effectiveRegistrationDate = LocalDate.now();
180	        }
181	        else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
182	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
183	        }
184	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
185	        owner.setRegistrationDate(registrationDate);
186	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
187	            return new ResponseEntity<>(HttpStatus.CONFLICT);
188	        }
189	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
190	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
191	        }
192	        // The householdId is deterministic: the first twelve hex characters of SHA-256 over
193	        // '<normalizedLastName>|<postcode>'. Owners sharing a last name and postcode therefore
194	        // share the household automatically. An owner without a postcode has no household.
195	        boolean declaredHouseholdMember = false;
196	        if (owner.getPostcode() != null) {
197	            String householdId = householdId(householdKey(owner.getLastName()), owner.getPostcode());
198	            owner.setHouseholdId(householdId);
199	            // A second owner sharing a household (same lastName + postcode) but with a distinct
200	            // identity is a legitimate additional household member — true duplicates are still
201	            // caught by the identityKey check below. 'sharesHousehold' opts such an owner in as a
202	            // declared member so it is not additionally flagged as a possible duplicate.
203	            boolean householdOccupied = false;
204	            for (Owner existing : this.clinicService.findAllOwners()) {
205	                if (existing.isDeleted()) {
206	                    continue;
207	                }
208	                if (householdId.equals(computeHouseholdId(existing))) {
209	                    householdOccupied = true;
210	                    break;
211	                }
212	            }
213	            if (householdOccupied && Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
214	                declaredHouseholdMember = true;
215	            }
216	        }
217	        // Consolidated duplicate detection: reject only when the whole identityKey
218	        // (SHA-256 over normalizedTelephone | lowerEmail | soundex(lastName)) matches an
219	        // existing owner's. This is the single duplicate check; owners sharing a household
220	        // (same last name and postcode) but with different telephones produce different keys
221	        // and are no longer rejected here — they surface as soft matches below.
222	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
223	        for (Owner existing : this.clinicService.findAllOwners()) {
224	            if (existing.isDeleted()) {
225	                continue;
226	            }
227	            if (identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
228	                existing.getEmail(), existing.getLastName()))) {
229	                return new ResponseEntity<>(HttpStatus.CONFLICT);
230	            }
231	        }
232	        // Soft-match: the owner is not a hard (identityKey) duplicate, but if it shares an
233	        // existing owner's last name and postcode while having a different normalized
234	        // telephone it is still created and flagged as a possible duplicate of that owner. A
235	        // declared household member, however, is not a suspected duplicate, so it is never flagged.
236	        if (declaredHouseholdMember) {
237	            owner.setPossibleDuplicate(false);
238	        }
239	        else {
240	            applyPossibleDuplicate(owner);
241	        }
242	        owner.setCustomerCode(deduplicatedCustomerCode(
243	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
244	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
245	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
246	        this.clinicService.saveOwner(owner);
247	        if (idempotencyKey != null) {
248	            idempotentCreates.put(idempotencyKey, owner.getId());
249	        }
250	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
251	        Map<String, Integer> householdSizes = householdSizes();
252	        applyMembership(ownerDto, owner, householdSizes);
253	        capMembershipLevelToHousehold(ownerDto, owner, householdSizes);
254	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
255	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
256	            ownerDto.getMembershipLevel(), owner.getMembershipNumber());
257	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
258	        headers.setLocation(UriComponentsBuilder.newInstance()
259	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
260	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
261	    }
262	
263	    /**
264	     * Reads the {@code Idempotency-Key} header of the request currently being handled, used to make
265	     * owner creation idempotent. Returns the trimmed key when present and non-blank, otherwise
266	     * {@code null} (including when there is no active servlet request), so a missing or blank key
267	     * simply means "no idempotency" and the create proceeds normally.
268	     *
269	     * @return the current request's idempotency key, or {@code null} when none is supplied
270	     */
271	    private static String currentIdempotencyKey() {
272	        RequestAttributes attributes = RequestContextHolder.getRequestAttributes();
273	        if (!(attributes instanceof ServletRequestAttributes servletAttributes)) {
274	            return null;
275	        }
276	        String key = servletAttributes.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
277	        if (key == null || key.isBlank()) {
278	            return null;
279	        }
280	        return key.trim();
281	    }
282	
283	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
284	    @Override
285	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
286	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
287	        if (currentOwner == null) {
288	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
289	        }
290	        currentOwner.setAddress(ownerFieldsDto.getAddress());
291	        currentOwner.setCity(ownerFieldsDto.getCity());
292	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
293	        currentOwner.setLastName(ownerFieldsDto.getLastName());
294	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
295	        this.clinicService.saveOwner(currentOwner);
296	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
297	    }
298	
299	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
300	    @Transactional
301	    @Override
302	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
303	        Owner owner = this.clinicService.findOwnerById(ownerId);
304	        if (owner == null) {
305	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
306	        }
307	        // Soft delete: the row is retained and flagged deleted rather than removed, so the
308	        // owner is still readable via GET but is ignored by the create duplicate/identity checks.
309	        owner.setDeleted(true);
310	        this.clinicService.saveOwner(owner);
311	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
312	    }
313	
314	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
315	    @Override
316	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
317	        Owner owner = this.clinicService.findOwnerById(ownerId);
318	        if (owner == null) {
319	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
320	        }
321	        HttpHeaders headers = new HttpHeaders();
322	        Pet pet = petMapper.toPet(petFieldsDto);
323	        owner.setId(ownerId);
324	        pet.setOwner(owner);
325	        pet.getType().setName(null);
326	        this.clinicService.savePet(pet);
327	        PetDto petDto = petMapper.toPetDto(pet);
328	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
329	            .buildAndExpand(pet.getId()).toUri());
330	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
331	    }
332	
333	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
334	    @Override
335	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
336	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
337	        if (currentOwner != null) {
338	            Pet currentPet = this.clinicService.findPetById(petId);
339	            if (currentPet != null) {
340	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
341	                currentPet.setName(petFieldsDto.getName());
342	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
343	                this.clinicService.savePet(currentPet);
344	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
345	            }
346	        }
347	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
348	    }
349	
350	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
351	    @Override
352	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
353	        HttpHeaders headers = new HttpHeaders();
354	        Visit visit = visitMapper.toVisit(visitFieldsDto);
355	        Pet pet = new Pet();
356	        pet.setId(petId);
357	        visit.setPet(pet);
358	        this.clinicService.saveVisit(visit);
359	        VisitDto visitDto = visitMapper.toVisitDto(visit);
360	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
361	            .buildAndExpand(visit.getId()).toUri());
362	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
363	    }
