365	
366	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
367	    @Override
368	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
369	        Owner owner = this.clinicService.findOwnerById(ownerId);
370	        if (owner != null) {
371	            Pet pet = owner.getPet(petId);
372	            if (pet != null) {
373	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
374	            }
375	        }
376	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
377	    }
378	
379	    /**
380	     * The maximum number of owners permitted per city. Owner creation is rejected once the
381	     * owner's city already contains this many owners.
382	     */
383	    private static final int MAX_OWNERS_PER_CITY = 50;
384	
385	    /**
386	     * Counts how many existing owners live in the given city, compared case-insensitively.
387	     * This is evaluated before the new owner is persisted, so the owner being created is not
388	     * included in the count.
389	     *
390	     * @param city the new owner's city
391	     * @return the number of existing owners in that city
392	     */
393	    private int countOwnersInCity(String city) {
394	        int count = 0;
395	        for (Owner existing : this.clinicService.findAllOwners()) {
396	            if (city.equalsIgnoreCase(existing.getCity())) {
397	                count++;
398	            }
399	        }
400	        return count;
401	    }
402	
403	    /**
404	     * The maximum number of owners that may be created in a single business day. Owner
405	     * creation is rejected once this many owners already fall on the new owner's adjusted
406	     * business day {@code registrationDate}.
407	     */
408	    private static final int MAX_OWNERS_PER_DAY = 100;
409	
410	    /**
411	     * The fixed list of public holidays that the business-day roll skips over. A date that
412	     * lands on one of these is rolled forward to the next non-holiday business day.
413	     */
414	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
415	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
416	        LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
417	        LocalDate.parse("2026-12-28"));
418	
419	    /**
420	     * Rolls a date forward to the next business day: a Saturday, Sunday or listed public
421	     * holiday is moved forward one day at a time until a non-holiday weekday is reached,
422	     * while a date that is already a non-holiday weekday is returned unchanged.
423	     *
424	     * @param date the date to adjust
425	     * @return the same date if it is a non-holiday weekday, otherwise the next such day
426	     */
427	    private LocalDate toBusinessDay(LocalDate date) {
428	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
429	                || PUBLIC_HOLIDAYS.contains(date)) {
430	            date = date.plusDays(1);
431	        }
432	        return date;
433	    }
434	
435	    /**
436	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
437	     * registrationDate} rolls forward to the same business day. This is evaluated before the
438	     * new owner is persisted, so the owner being created is not included in the count.
439	     *
440	     * @param businessDay the adjusted business day to count against
441	     * @return the number of existing owners registered on that business day
442	     */
443	    private int countOwnersRegisteredOn(LocalDate businessDay) {
444	        int count = 0;
445	        for (Owner existing : this.clinicService.findAllOwners()) {
446	            LocalDate existingDate = existing.getRegistrationDate();
447	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
448	                count++;
449	            }
450	        }
451	        return count;
452	    }
453	
454	    /**
455	     * The number of owners that may be created on a single business day before a bulk-signup
456	     * warning is raised. Once more than this many owners already fall on the current business
457	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
458	     */
459	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
460	
461	    /**
462	     * Reports whether an unusually high number of owners have been created for today's business
463	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
464	     * the business day that {@code LocalDate.now()} rolls forward to.
465	     *
466	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
467	     */
468	    private boolean isBulkSignupDay() {
469	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
470	    }
471	
472	    /**
473	     * Builds the customer code for a newly created owner, formatted
474	     * {@code '<REGION>-<HASH8>'} where {@code REGION} is the canonical region
475	     * {@link OwnerLocality#forPostcodeOrUnknown derived from the postcode} (or
476	     * {@code "UNKNOWN"} when the postcode resolves no region) and {@code HASH8} is the
477	     * first eight upper-case hex characters of the SHA-256 digest of
478	     * {@code normalizedTelephone + lastName}. The code carries no sequence number, so it is
479	     * stable for a given telephone and last name rather than dependent on creation order.
480	     *
481	     * @param postcode            the owner's postcode (may be {@code null})
482	     * @param normalizedTelephone the owner's normalized E.164 telephone
483	     * @param lastName            the owner's last name
484	     * @return the assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
485	     */
486	    private static String customerCode(String postcode, String normalizedTelephone, String lastName) {
487	        String region = org.springframework.samples.petclinic.mapper.OwnerLocality.forPostcodeOrUnknown(postcode);
488	        return region + "-" + sha256Hex8(normalizedTelephone + lastName);
489	    }
490	
491	    /**
492	     * De-duplicates a freshly computed {@code base} customer code against the codes already
493	     * assigned to existing owners. When {@code base} is free it is returned unchanged;
494	     * otherwise {@code '-<n>'} is appended with the smallest {@code n} of two or more that
495	     * yields a code no existing owner holds.
496	     *
497	     * @param base the computed {@code '<REGION>-<HASH8>'} customer code
498	     * @return {@code base}, or {@code base + "-<n>"} de-duplicated to be unique
499	     */
500	    private String deduplicatedCustomerCode(String base) {
501	        Set<String> existing = new HashSet<>();
502	        for (Owner owner : this.clinicService.findAllOwners()) {
503	            if (owner.getCustomerCode() != null) {
504	                existing.add(owner.getCustomerCode());
505	            }
506	        }
507	        if (!existing.contains(base)) {
508	            return base;
509	        }
510	        int n = 2;
511	        while (existing.contains(base + "-" + n)) {
512	            n++;
513	        }
514	        return base + "-" + n;
515	    }
516	
517	    /**
518	     * Returns the first eight upper-case hex characters of the SHA-256 digest of the UTF-8
519	     * bytes of {@code source} — the {@code HASH8} component of an owner's customer code.
520	     *
521	     * @param source the string to hash
522	     * @return the first eight upper-case hex characters of {@code SHA-256(source)}
523	     */
524	    private static String sha256Hex8(String source) {
525	        try {
526	            byte[] digest = MessageDigest.getInstance("SHA-256")
527	                .digest(source.getBytes(StandardCharsets.UTF_8));
528	            StringBuilder hex = new StringBuilder(digest.length * 2);
529	            for (byte b : digest) {
530	                hex.append(String.format("%02x", b));
531	            }
532	            return hex.substring(0, 8).toUpperCase();
533	        } catch (NoSuchAlgorithmException e) {
534	            throw new IllegalStateException("SHA-256 not available", e);
535	        }
536	    }
537	
538	    /**
539	     * Builds the membership number for a newly created owner, formatted
540	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
541	     * customer code and {@code YY} is the last two digits of the fiscal year of the owner's
542	     * business-day-adjusted registration date, zero-padded to two digits. The fiscal year
543	     * starts on 1 July and is named by the calendar year it ends in.
544	     *
545	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'NSW-1A2B3C4D'})
546	     * @param registrationDate the owner's business-day-adjusted registration date
547	     * @return the assigned membership number (e.g. {@code 'NSW-1A2B3C4D-M27'})
548	     */
549	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
550	        int fiscalYear = org.springframework.samples.petclinic.mapper.FiscalYear.yearValue(registrationDate);
551	        return String.format("%s-M%02d", customerCode, Math.floorMod(fiscalYear, 100));
552	    }
553	
554	    /**
555	     * Counts how many existing owners share the given first and last name, compared
556	     * case-insensitively. This is evaluated before the new owner is persisted, so the
557	     * owner being created is not included in the count.
558	     *
559	     * @param firstName the new owner's first name
560	     * @param lastName  the new owner's last name
561	     * @return the number of existing owners with the same first and last name
562	     */
563	    private int countNamesakes(String firstName, String lastName) {
564	        int count = 0;
565	        for (Owner existing : this.clinicService.findAllOwners()) {
566	            if (firstName.equalsIgnoreCase(existing.getFirstName())
567	                && lastName.equalsIgnoreCase(existing.getLastName())) {
568	                count++;
569	            }
570	        }
571	        return count;
572	    }
573	
574	    /**
575	     * Canonical expansions applied to common street-type abbreviations during address
576	     * normalization. Keys and values are upper-cased so the lookup runs after the address
577	     * has itself been upper-cased.
578	     */
579	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
580	        "ST", "STREET",
581	        "RD", "ROAD",
582	        "AVE", "AVENUE");
583	
584	    /**
585	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
586	     * every run of internal whitespace is collapsed to a single space, the result is
587	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
588	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
589	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
590	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
591	     * returned and compared for household duplicates; an address that is blank once
592	     * normalized fails the required-field check.
593	     *
594	     * @param address the raw address value supplied by the client
595	     * @return the normalized address (empty string when {@code address} is null or blank)
596	     */
597	    /**
598	     * Normalizes the address an owner supplies, preferring the structured form, and stores the
599	     * normalized structured lines on the owner. When a non-blank {@code addressLine1} is present
600	     * the structured fields are used: {@code addressLine1} (and {@code addressLine2}, when
601	     * present) are {@link #normalizeAddress normalized} and set on the owner, and the composed
602	     * address returned is the normalized {@code addressLine1} with a single space and the
603	     * normalized {@code addressLine2} appended when {@code addressLine2} is present. Otherwise
604	     * the flat {@code address} is normalized and returned, and the structured lines are left
605	     * unset. The returned value becomes the owner's stored {@code address}, read by everything
606	     * downstream (household hash, postcode validation and locality); an owner that supplies
607	     * neither form yields an empty string, failing the required-address check.
608	     *
609	     * @param owner          the owner being created, whose structured address lines are set here
610	     * @param ownerFieldsDto the submitted owner fields
611	     * @return the composed, normalized address (empty string when no address form is supplied)
612	     */
613	    private static String applyAddress(Owner owner, OwnerFieldsDto ownerFieldsDto) {
614	        String addressLine1 = ownerFieldsDto.getAddressLine1();
615	        if (addressLine1 != null && !addressLine1.isBlank()) {
616	            String normalizedLine1 = normalizeAddress(addressLine1);
617	            owner.setAddressLine1(normalizedLine1);
618	            String addressLine2 = ownerFieldsDto.getAddressLine2();
619	            if (addressLine2 != null && !addressLine2.isBlank()) {
620	                String normalizedLine2 = normalizeAddress(addressLine2);
621	                owner.setAddressLine2(normalizedLine2);
622	                return normalizedLine1 + " " + normalizedLine2;
623	            }
624	            owner.setAddressLine2(null);
625	            return normalizedLine1;
626	        }
627	        owner.setAddressLine1(null);
628	        owner.setAddressLine2(null);
629	        return normalizeAddress(ownerFieldsDto.getAddress());
630	    }
631	
632	    private static String normalizeAddress(String address) {
633	        if (address == null) {
634	            return "";
635	        }
636	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
637	        if (collapsed.isEmpty()) {
638	            return "";
639	        }
640	        StringBuilder normalized = new StringBuilder(collapsed.length());
641	        for (String token : collapsed.split(" ")) {
642	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
643	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
644	            if (normalized.length() > 0) {
645	                normalized.append(' ');
646	            }
647	            normalized.append(expanded != null ? expanded : token);
648	        }
649	        return normalized.toString();
650	    }
651	
652	    /**
653	     * Normalizes a last name or address for household-duplicate comparison: leading and
654	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
655	     * single space and the result is lower-cased. Two owners are considered to share a
656	     * household when both their last names and addresses produce the same key.
657	     *
658	     * @param value the raw last name or address value
659	     * @return the normalized comparison key (empty string when {@code value} is null)
660	     */
661	    private static String householdKey(String value) {
662	        if (value == null) {
663	            return "";
664	        }
665	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
666	    }
667	
668	    /**
669	     * Derives the stable shared household identifier for the given normalized last name key
670	     * and postcode. The identifier is deterministic — the same household (same
671	     * {@link #householdKey normalized} last name and postcode) always maps to the same
672	     * value — so every owner in a household is assigned an identical id. It is the
673	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
674	     * '<lastNameKey>|<postcode>'}.
675	     *
676	     * @param lastNameKey the normalized last name key
677	     * @param postcode    the owner's postcode
678	     * @return the shared household identifier
679	     */
680	    private static String householdId(String lastNameKey, String postcode) {
681	        String source = lastNameKey + "|" + postcode;
682	        try {
683	            byte[] digest = MessageDigest.getInstance("SHA-256")
684	                .digest(source.getBytes(StandardCharsets.UTF_8));
685	            StringBuilder hex = new StringBuilder(digest.length * 2);
686	            for (byte b : digest) {
687	                hex.append(String.format("%02x", b));
688	            }
689	            return hex.substring(0, 12).toUpperCase();
690	        } catch (NoSuchAlgorithmException e) {
691	            throw new IllegalStateException("SHA-256 not available", e);
692	        }
693	    }
694	
695	    /**
696	     * Computes the deterministic {@link #householdId household id} an existing owner belongs to,
697	     * derived from its {@link #householdKey normalized} last name and its postcode. Returns
698	     * {@code null} when the owner has no postcode (such an owner has no household), so it never
699	     * collides with a computed household id.
700	     *
701	     * @param owner the existing owner
702	     * @return the owner's household id, or {@code null} when it has no postcode
703	     */
704	    private static String computeHouseholdId(Owner owner) {
705	        if (owner.getPostcode() == null) {
706	            return null;
707	        }
708	        return householdId(householdKey(owner.getLastName()), owner.getPostcode());
709	    }
710	
711	    /**
712	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
713	     * dto, sizing the owner's household from all owners so the household-of-three-or-more
714	     * factor is scored correctly. Use {@link #applyMembership(OwnerDto, Owner, Map)} instead
715	     * when mapping a collection to size every household from a single scan.
716	     *
717	     * @param ownerDto the dto to populate
718	     * @param owner    the owner being mapped
719	     */
720	    private void applyMembership(OwnerDto ownerDto, Owner owner) {
721	        applyMembership(ownerDto, owner, householdSizes());
722	    }
723	
724	    /**
725	     * Populates an owner's {@code membershipPoints} and {@code membershipLevel} on the given
726	     * dto using a pre-computed map of household id to member count.
727	     *
728	     * @param ownerDto       the dto to populate
729	     * @param owner          the owner being mapped
730	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
731	     */
732	    private void applyMembership(OwnerDto ownerDto, Owner owner, Map<String, Integer> householdSizes) {
733	        int householdSize = owner.getHouseholdId() == null ? 1
734	            : householdSizes.getOrDefault(owner.getHouseholdId(), 1);
735	        int points = MembershipPoints.points(owner, householdSize);
736	        ownerDto.setMembershipPoints(points);
737	        ownerDto.setMembershipLevel(MembershipPoints.level(points));
738	    }
739	
740	    /**
741	     * Caps a newly created owner's {@code membershipLevel} at one above the highest
742	     * {@code membershipLevel} among the other current members of its household, writing the
743	     * capped value back onto the dto and returning it. A member's current level is scored the
744	     * same way as {@link #applyMembership}, using {@code householdSizes} so the
745	     * household-of-three-or-more factor reflects the household as it now stands. When the owner
746	     * has no household, or is the only member of its household, no cap applies and the level is
747	     * returned unchanged.
748	     *
749	     * @param ownerDto       the newly created owner's dto, with its uncapped membership already applied
750	     * @param owner          the newly created owner (already saved, so it has an id)
751	     * @param householdSizes household id to member count, as returned by {@link #householdSizes()}
752	     * @return the resulting (possibly capped) membership level
753	     */
754	    private int capMembershipLevelToHousehold(OwnerDto ownerDto, Owner owner,
755	        Map<String, Integer> householdSizes) {
756	        int level = ownerDto.getMembershipLevel();
757	        String householdId = owner.getHouseholdId();
758	        if (householdId == null) {
759	            return level;
760	        }
761	        Integer maxMemberLevel = null;
762	        for (Owner existing : this.clinicService.findAllOwners()) {
763	            if (existing.isDeleted() || existing.getId().equals(owner.getId())) {
764	                continue;
765	            }
766	            if (householdId.equals(existing.getHouseholdId())) {
767	                int size = householdSizes.getOrDefault(householdId, 1);
768	                int memberLevel = MembershipPoints.level(MembershipPoints.points(existing, size));
769	                maxMemberLevel = maxMemberLevel == null ? memberLevel
770	                    : Math.max(maxMemberLevel, memberLevel);
771	            }
772	        }
773	        if (maxMemberLevel != null && level > maxMemberLevel + 1) {
774	            level = maxMemberLevel + 1;
775	            ownerDto.setMembershipLevel(level);
776	        }
777	        return level;
778	    }
779	
780	    /**
781	     * Counts how many owners belong to each household, keyed by household id. Owners without a
782	     * household id (no postcode) are excluded — such an owner is its own single-member household.
783	     *
784	     * @return a map from household id to the number of owners sharing it
785	     */
786	    private Map<String, Integer> householdSizes() {
787	        Map<String, Integer> sizes = new java.util.HashMap<>();
788	        for (Owner existing : this.clinicService.findAllOwners()) {
789	            String householdId = existing.getHouseholdId();
790	            if (householdId != null) {
791	                sizes.merge(householdId, 1, Integer::sum);
792	            }
793	        }
794	        return sizes;
795	    }
796	
797	    /**
798	     * Applies soft-match (possible-duplicate) detection to a new owner that has already
799	     * cleared hard {@code identityKey} duplicate rejection. The owner is flagged as a
800	     * possible duplicate when a non-deleted existing owner shares its {@link
801	     * OwnerIdentity#soundex soundex(lastName)} and its postcode while producing a different
802	     * {@code identityKey}; {@code possibleDuplicateOf} is then set to that existing owner's id.
803	     * Because the telephone is part of the identity key, two owners with the same last name and
804	     * postcode but different telephones differ in their keys and so surface here as a soft match
805	     * rather than a hard duplicate. When several existing owners match, the one with the lowest
806	     * id is chosen so the result is deterministic. When no such owner exists — or the new owner
807	     * has no postcode to compare — {@code possibleDuplicate} is set to {@code false} and no
808	     * matching id is recorded.
809	     *
810	     * @param owner the new owner, already normalized (E.164 telephone, validated postcode)
811	     */
812	    private void applyPossibleDuplicate(Owner owner) {
813	        owner.setPossibleDuplicate(false);
814	        if (owner.getPostcode() == null) {
815	            return;
816	        }
817	        String soundex = OwnerIdentity.soundex(owner.getLastName());
818	        String identityKey = OwnerIdentity.identityKey(owner.getTelephone(), owner.getEmail(), owner.getLastName());
819	        Owner match = null;
820	        for (Owner existing : this.clinicService.findAllOwners()) {
821	            if (existing.isDeleted()) {
822	                continue;
823	            }
824	            if (soundex.equals(OwnerIdentity.soundex(existing.getLastName()))
825	                && owner.getPostcode().equals(existing.getPostcode())
826	                && !identityKey.equals(OwnerIdentity.identityKey(toE164(existing.getTelephone()),
827	                    existing.getEmail(), existing.getLastName()))) {
828	                if (match == null || (existing.getId() != null
829	                    && existing.getId() < match.getId())) {
830	                    match = existing;
831	                }
832	            }
833	        }
834	        if (match != null) {
835	            owner.setPossibleDuplicate(true);
836	            owner.setPossibleDuplicateOf(match.getId());
837	        }
838	    }
839	
840	    /**
841	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
842	     * and brackets are stripped. When the number already carries a leading {@code '+'}
843	     * and country code these are kept; a number written in national trunk form (a leading
844	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
845	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
846	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
847	     * after the {@code '+'}, and its national-number length must be valid for the detected
848	     * country code (see {@link #hasValidNationalLength}).
849	     *
850	     * @param telephone the raw telephone value supplied by the client
851	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
852	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
853	     */
854	    private static String toE164(String telephone) {
855	        if (telephone == null) {
856	            return null;
857	        }
858	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
859	        String digits;
860	        if (cleaned.startsWith("+")) {
861	            digits = cleaned.substring(1);
862	        } else if (cleaned.startsWith("0")) {
863	            digits = "61" + cleaned.substring(1);
864	        } else {
865	            digits = "1" + cleaned;
866	        }
867	        if (!digits.matches("[0-9]{8,15}")) {
868	            return null;
869	        }
870	        if (!hasValidNationalLength(digits)) {
871	            return null;
872	        }
873	        return "+" + digits;
874	    }
875	
876	    /**
877	     * Validates the national-number length of an E.164 digit string against its country
878	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
879	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
880	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
881	     *
882	     * @param digits the E.164 digits (without the leading {@code '+'})
883	     * @return {@code true} when the national-number length is valid for the country code
884	     */
885	    private static boolean hasValidNationalLength(String digits) {
886	        if (digits.startsWith("61")) {
887	            return digits.length() - 2 == 9;
888	        }
889	        if (digits.startsWith("1")) {
890	            return digits.length() - 1 == 10;
891	        }
892	        return true;
893	    }
894	
895	    /**
896	     * Inclusive 4-digit postcode ranges permitted for each canonical region: NSW 2000-2099,
897	     * VIC 3000-3099 and QLD 4000-4099. A region absent from this table (e.g. the {@code
898	     * "UNKNOWN"} derived for a city with no known region) imposes no range restriction.
899	     */
900	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
901	        "NSW", new int[] {2000, 2099},
902	        "VIC", new int[] {3000, 3099},
903	        "QLD", new int[] {4000, 4099});
904	
905	    /**
906	     * Validates an owner's postcode for creation. A postcode is only ever validated when
907	     * present (an absent postcode is optional and accepted). When present it must be exactly
908	     * four digits and, for a city whose {@link OwnerLocality#forCity region} has a known
909	     * postcode range, must fall inside that inclusive range (NSW 2000-2099, VIC 3000-3099,
910	     * QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
911	     *
912	     * @param postcode the supplied postcode (never {@code null} here)
913	     * @param city     the owner's city, used to derive the region
914	     * @return {@code true} when the postcode is valid for the city, {@code false} otherwise
915	     *         (signalling a 400 Bad Request)
916	     */
917	    private static boolean isValidPostcode(String postcode, String city) {
918	        if (!postcode.matches("[0-9]{4}")) {
919	            return false;
920	        }
921	        int[] range = REGION_POSTCODES.get(
922	            org.springframework.samples.petclinic.mapper.OwnerLocality.forCity(city));
923	        if (range == null) {
924	            return true;
925	        }
926	        int value = Integer.parseInt(postcode);
927	        return value >= range[0] && value <= range[1];
928	    }
929	
930	    /**
931	     * Disposable email domains that are not accepted for owner creation. An owner whose
932	     * email domain (compared case-insensitively) is in this set is rejected with a 400
933	     * Bad Request.
934	     */
935	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
936	        "mailinator.com", "tempmail.com", "guerrillamail.com");
937	
938	    /**
939	     * Normalizes an owner email for creation. A present email must be a syntactically
940	     * valid address whose domain is not on the disposable-domain blocklist ({@link
941	     * #DISPOSABLE_EMAIL_DOMAINS}); the returned value is lower-cased.
942	     *
943	     * @param email the raw email value supplied by the client (never {@code null} here)
944	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
945	     *         address or its domain is a disposable domain (signalling a 400 Bad Request)
946	     */
947	    private static String normalizeEmail(String email) {
948	        String trimmed = email.trim();
949	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
950	            return null;
951	        }
952	        String normalized = trimmed.toLowerCase();
953	        String domain = normalized.substring(normalized.indexOf('@') + 1);
954	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
955	            return null;
956	        }
957	        return normalized;
958	    }
959	}
